### 2. API Client

```typescript
// api/preferencesClient.ts

import { UserPreferences, PreferencesResponse, ApiError, ApiErrorResponse } from '../types/preferences.types';

/**
 * Configuration for API client
 */
export interface ApiClientConfig {
  baseUrl?: string;
  getAuthToken: () => string | null;
}

/**
 * User Preferences API Client
 */
export class PreferencesApiClient {
  private baseUrl: string;
  private getAuthToken: () => string | null;

  constructor(config: ApiClientConfig) {
    this.baseUrl = config.baseUrl || '';
    this.getAuthToken = config.getAuthToken;
  }

  /**
   * Fetch user preferences from the API
   * @throws {ApiError} If authentication fails or request errors
   * @returns {Promise<UserPreferences>} User preference settings
   */
  async getUserPreferences(): Promise<UserPreferences> {
    const token = this.getAuthToken();

    if (!token) {
      throw new ApiError('Authentication token not found', 401);
    }

    try {
      const response = await fetch(`${this.baseUrl}/api/user/preferences`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        await this.handleErrorResponse(response);
      }

      const data: PreferencesResponse = await response.json();
      return data.data;
    } catch (error) {
      if (error instanceof ApiError) {
        throw error;
      }
      // Network or parsing errors
      throw new ApiError(
        error instanceof Error ? error.message : 'Network error occurred',
        0
      );
    }
  }

  /**
   * Handle non-OK HTTP responses
   */
  private async handleErrorResponse(response: Response): Promise<never> {
    let errorResponse: ApiErrorResponse;

    try {
      errorResponse = await response.json();
    } catch {
      errorResponse = {
        error: response.statusText || 'Unknown error',
      };
    }

    throw new ApiError(
      errorResponse.error || 'Request failed',
      response.status,
      errorResponse
    );
  }
}

/**
 * Factory function to create API client instance
 */
export function createPreferencesClient(config: ApiClientConfig): PreferencesApiClient {
  return new PreferencesApiClient(config);
}
