### 3. React Hook for State Management (Optional but useful)

```typescript
// hooks/useUserPreferences.ts

import { useState, useEffect, useCallback } from 'react';
import { PreferencesApiClient } from '../api/preferencesClient';
import { UserPreferences, LoadingState, ApiError } from '../types/preferences.types';

/**
 * React hook for managing user preferences state
 */
export function useUserPreferences(apiClient: PreferencesApiClient) {
  const [state, setState] = useState<LoadingState<UserPreferences>>({
    data: null,
    loading: false,
    error: null,
  });

  const fetchPreferences = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const data = await apiClient.getUserPreferences();
      setState({ data, loading: false, error: null });
    } catch (error) {
      const apiError = error instanceof ApiError 
        ? error 
        : new ApiError('Unknown error occurred', 0);
      setState({ data: null, loading: false, error: apiError });
    }
  }, [apiClient]);

  useEffect(() => {
    fetchPreferences();
  }, [fetchPreferences]);

  return {
    preferences: state.data,
    loading: state.loading,
    error: state.error,
    refetch: fetchPreferences,
  };
}
