// tests/preferencesClient.test.ts

import { PreferencesApiClient, ApiError } from '../api/preferencesClient';
import { UserPreferences } from '../types/preferences.types';

// Mock fetch globally
global.fetch = jest.fn();

describe('PreferencesApiClient', () => {
  let client: PreferencesApiClient;
  let mockGetAuthToken: jest.Mock;

  beforeEach(() => {
    mockGetAuthToken = jest.fn();
    client = new PreferencesApiClient({
      baseUrl: 'http://localhost:5000',
      getAuthToken: mockGetAuthToken,
    });
    jest.clearAllMocks();
  });

  describe('getUserPreferences', () => {
    it('should successfully fetch user preferences', async () => {
      const mockPreferences: UserPreferences = {
        user_id: 1,
        theme: 'dark',
        language: 'en',
        timezone: 'UTC',
        notifications: true,
      };

      mockGetAuthToken.mockReturnValue('valid-token');
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          success: true,
          data: mockPreferences,
        }),
      });

      const result = await client.getUserPreferences();

      expect(result).toEqual(mockPreferences);
      expect(global.fetch).toHaveBeenCalledWith(
        'http://localhost:5000/api/user/preferences',
        {
          method: 'GET',
          headers: {
            'Authorization': 'Bearer valid-token',
            'Content-Type': 'application/json',
          },
        }
      );
    });

    it('should throw ApiError when token is missing', async () => {
      mockGetAuthToken.mockReturnValue(null);

      await expect(client.getUserPreferences()).rejects.toThrow(ApiError);
      await expect(client.getUserPreferences()).rejects.toMatchObject({
        statusCode: 401,
        message: 'Authentication token not found',
      });
    });

    it('should handle 401 unauthorized error', async () => {
      mockGetAuthToken.mockReturnValue('invalid-token');
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: false,
        status: 401,
        json: async () => ({
          error: 'Invalid token',
        }),
      });

      await expect(client.getUserPreferences()).rejects.toThrow(ApiError);
      await expect(client.getUserPreferences()).rejects.toMatchObject({
        statusCode: 401,
        message: 'Invalid token',
      });
    });

    it('should handle 404 not found error', async () => {
      mockGetAuthToken.mockReturnValue('valid-token');
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: false,
        status: 404,
        json: async () => ({
          error: 'User preferences not found',
          message: 'No preferences found for user 999',
        }),
      });

      await expect(client.getUserPreferences()).rejects.toThrow(ApiError);
      await expect(client.getUserPreferences()).rejects.toMatchObject({
        statusCode: 404,
        message: 'User preferences not found',
      });
    });

    it('should handle 500 internal server error', async () => {
      mockGetAuthToken.mockReturnValue('valid-token');
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: false,
        status: 500,
        json: async () => ({
          error: 'Internal server error',
          message: 'An unexpected error occurred',
        }),
      });

      await expect(client.getUserPreferences()).rejects.toThrow(ApiError);
      await expect(client.getUserPreferences()).rejects.toMatchObject({
        statusCode: 500,
      });
    });

    it('should handle network errors', async () => {
      mockGetAuthToken.mockReturnValue('valid-token');
      (global.fetch as jest.Mock).mockRejectedValueOnce(new Error('Network failure'));

      await expect(client.getUserPreferences()).rejects.toThrow(ApiError);
      await expect(client.getUserPreferences()).rejects.toMatchObject({
        message: 'Network failure',
        statusCode: 0,
      });
    });

    it('should handle malformed JSON responses', async () => {
      mockGetAuthToken.mockReturnValue('valid-token');
