### 5. Example Usage

```typescript
// example/usage.example.ts

import { createPreferencesClient } from '../api/preferencesClient';
import { useUserPreferences } from '../hooks/useUserPreferences';

// Example 1: Direct API client usage
function exampleDirectUsage() {
  const client = createPreferencesClient({
    baseUrl: 'http://localhost:5000',
    getAuthToken: () => localStorage.getItem('auth_token'),
  });

  async function loadPreferences() {
    try {
      const preferences = await client.getUserPreferences();
      console.log('User preferences:', preferences);
      // Apply preferences to UI
      document.body.className = preferences.theme;
    } catch (error) {
      if (error instanceof ApiError) {
        if (error.statusCode === 401) {
          // Redirect to login
          window.location.href = '/login';
        } else {
          console.error('Failed to load preferences:', error.message);
        }
      }
    }
  }

  loadPreferences();
}

// Example 2: React component usage
function UserPreferencesComponent() {
  const client = createPreferencesClient({
    baseUrl: process.env.REACT_APP_API_URL || '',
    getAuthToken: () => localStorage.getItem('auth_token'),
  });

  const { preferences, loading, error, refetch } = useUserPreferences(client);

  if (loading) return <div>Loading preferences...</div>;
  if (error) return <div>Error: {error.message}</div>;
  if (!preferences) return null;

  return (
    <div className={preferences.theme}>
      <h2>User Preferences</h2>
      <p>Theme: {preferences.theme}</p>
      <p>Language: {preferences.language}</p>
      <p>Timezone: {preferences.timezone}</p>
      <p>Notifications: {preferences.notifications ? 'On' : 'Off'}</p>
      <button onClick={refetch}>Refresh</button>
    </div>
  );
}
